const crypto = require('crypto');
const e = $input.first().json;
const exec = e.execution || {};
const trigErr = (e.trigger && e.trigger.error) || {};
const report = {
  workflow: (e.workflow && e.workflow.name) || 'unknown workflow',
  node: exec.lastNodeExecuted || (trigErr.node && trigErr.node.name) || undefined,
  message: String((exec.error && exec.error.message) || trigErr.message || 'Unknown error').slice(0, 1000),
  executionId: exec.id ? String(exec.id) : undefined,
};
console.error('[LendLoop workflow failure]', JSON.stringify(report));
const rawBody = JSON.stringify(report);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET).update(`${timestamp}.${rawBody}`).digest('hex');
return [{ json: { rawBody, timestamp, signature } }];
